// Generated by `npm run images` from assets/image-manifest.json (public fields only).
import data from "./photos.json";

export type Category = "exterior" | "deck" | "living" | "dining" | "kitchen" | "bedroom" | "bathroom" | "details" | "family";

export interface Photo {
  id: string;
  width: number;
  height: number;
  category: Category;
  title: string;
  alt: string;
  focal: [number, number];
  featured: boolean;
  lqip?: string;
  /** srcset widths actually generated by scripts/optimize-images.mjs */
  widths: number[];
}

const BUCKETS = [640, 1280, 2048];
const bucketsFor = (w: number) => BUCKETS.filter((b) => b <= w + 8 || b === BUCKETS[0]);

const photos: Photo[] = data.map((i) => ({
  ...i,
  category: i.category as Category,
  focal: i.focal as [number, number],
  widths: bucketsFor(i.width),
}));

const byId = new Map(photos.map((p) => [p.id, p]));

export function photo(id: string): Photo {
  const p = byId.get(id);
  if (!p) throw new Error(`Unknown photo id "${id}" (see assets/image-manifest.json)`);
  return p;
}

/** Property photos only (excludes the decal crop and family photos). */
export const allPhotos = photos.filter((p) => p.id !== "storefront-decal" && p.category !== "family");

export const imgBase = `${import.meta.env.BASE_URL}images/`;

export function srcSet(p: Photo, format: "avif" | "webp") {
  return p.widths.map((w) => `${imgBase}${p.id}-${w}.${format} ${Math.min(w, p.width)}w`).join(", ");
}

/** Largest available WebP, used for a plain <img src>. */
export function fallbackSrc(p: Photo) {
  return `${imgBase}${p.id}-${p.widths[p.widths.length - 1]}.webp`;
}
